 page.set_viewport_size({'width':1440,'height':900});shot('winning-ticket')
 page.reload();page.wait_for_load_state('networkidle');check('Ticket deep link survives refresh',page.get_by_role('dialog').count()==1)
 close();page.get_by_role('button',name='Notifications',exact=True).click();page.get_by_role('button',name='Share This Win',exact=True).first.click();check('Share action opens share card',page.locator('.share-active').count()==1);close()
 visit('my-bets?ticket=BF-08091');text=page.get_by_role('dialog').inner_text();check('Lost result has no repeated accepted wording','Accepted Over' not in text and 'A losing selection' not in text)
 check('Final total score remains visible','Final Combined Score:' in text);shot('lost-ticket');close()
 visit('my-bets?ticket=BF-08088');check('Push result omits redundant equality wording','matched exactly' not in page.get_by_role('dialog').inner_text() and 'Accepted spread' not in page.get_by_role('dialog').inner_text());close()
 visit('profile')
 page.get_by_role('button',name='Show All Transactions',exact=True).click()
