 balance=page.locator('.balance-current strong').inner_text().replace('credits','').strip();header=page.locator('.header-balance strong').inner_text().strip();check('Profile balance matches header',balance==header)
 shot('balance-history')
 page.get_by_role('button',name='Feedback & Support',exact=True).click();check('Design Feedback option removed',page.get_by_role('dialog').locator('option').filter(has_text='Design Feedback').count()==0)
