 records=page.evaluate("JSON.parse(localStorage.getItem('boff-preview-feedback'))");check('Feedback user team league page attached',records[0]['username']=='cgurrie' and records[0]['leagueId']==L and records[0]['team'] and records[0]['page'].endswith('/profile'))
 visit('/platform');page.get_by_role('tab',name='Support Inbox',exact=True).click();check('Owner inbox shows saved message',page.locator('.support-message').inner_text().startswith('Review fixture:'))
 page.get_by_role('button',name='Mark Reviewed',exact=True).click();check('Owner can mark preview reviewed',page.get_by_role('button',name='Reviewed',exact=True).is_disabled());shot('support-inbox')
 page.get_by_role('tab',name='User Balances',exact=True).click();check('All users have balance history',page.get_by_label('Balance History Participant').locator('option').count()==13)
 page.get_by_label('Balance History Participant').select_option('nellyknowsball');check('Individual histories stay separated',page.locator('.balance-entry').count()==2 and page.locator('.balance-current strong').inner_text().startswith('250.00'))
 page.get_by_role('tab',name='Result Review',exact=True).click();check('Result review is automatic','do not need to submit a dispute' in page.locator('.review-example').inner_text())
 visit('my-bets?ticket=BF-08104');check('Open ticket shows score remaining forecast',all(x in page.get_by_role('dialog').locator('.ticket-progress').inner_text() for x in ['Current','Remaining','Forecast']));close()
 visit('my-bets?ticket=BF-08105');check('Season win progress visible',page.get_by_role('dialog').locator('progress[aria-label="Season Win Progress"]').count()==1);shot('season-progress');close()
 baseline=page.evaluate('Object.keys(localStorage).length')
